//! Shanten number, ported from `src/shanten.js`.
//!
//! The JS implementation uses a suit-wise table plus a DFS reference; this port
//! keeps the same DFS semantics (standard / seven pairs / thirteen orphans).
//! `tests/golden.rs` compares it with values generated by the JS engine.

pub fn eval_formula(sets: i32, taatsu: i32, pair: i32, open_sets: i32) -> i32 {
    8 - 2 * (sets + open_sets) - taatsu.min(4 - sets - open_sets) - pair
}

fn standard(counts: &[u8; 34], open_sets: i32) -> i32 {
    let mut c = *counts;
    let mut min = 99;
    dfs(&mut c, 0, 0, 0, 0, open_sets, &mut min);
    min
}

fn dfs(c: &mut [u8; 34], idx: usize, sets: i32, taatsu: i32, pair: i32, open_sets: i32, min: &mut i32) {
    let mut i = idx;
    while i < 34 && c[i] == 0 {
        i += 1;
    }
    if i >= 34 {
        let value = eval_formula(sets, taatsu, pair, open_sets);
        if value < *min {
            *min = value;
        }
        return;
    }
    if sets + open_sets > 4 {
        return;
    }
    let t = i;
    let n = (t % 9) as i32;
    if c[t] >= 3 {
        c[t] -= 3;
        dfs(c, t, sets + 1, taatsu, pair, open_sets, min);
        c[t] += 3;
    }
    if c[t] >= 2 {
        if pair == 0 {
            c[t] -= 2;
            dfs(c, t, sets, taatsu, 1, open_sets, min);
            c[t] += 2;
        }
        c[t] -= 2;
        dfs(c, t, sets, taatsu + 1, pair, open_sets, min);
        c[t] += 2;
    }
    if t < 27 && n <= 6 && c[t + 1] > 0 && c[t + 2] > 0 {
        c[t] -= 1;
        c[t + 1] -= 1;
        c[t + 2] -= 1;
        dfs(c, t, sets + 1, taatsu, pair, open_sets, min);
        c[t] += 1;
        c[t + 1] += 1;
        c[t + 2] += 1;
    }
    if t < 27 && n <= 7 && c[t + 1] > 0 {
        c[t] -= 1;
        c[t + 1] -= 1;
        dfs(c, t, sets, taatsu + 1, pair, open_sets, min);
        c[t] += 1;
        c[t + 1] += 1;
    }
    if t < 27 && n <= 6 && c[t + 2] > 0 {
        c[t] -= 1;
        c[t + 2] -= 1;
        dfs(c, t, sets, taatsu + 1, pair, open_sets, min);
        c[t] += 1;
        c[t + 2] += 1;
    }
    dfs(c, t + 1, sets, taatsu, pair, open_sets, min);
}

pub fn chiitoi(counts: &[u8; 34]) -> i32 {
    let mut pairs = 0;
    let mut kinds = 0;
    for &n in counts.iter() {
        if n >= 2 {
            pairs += 1;
        }
        if n > 0 {
            kinds += 1;
        }
    }
    6 - pairs + (7 - kinds).max(0)
}

pub fn kokushi(counts: &[u8; 34]) -> i32 {
    let mut kinds = 0;
    let mut pair = 0;
    for t in crate::tiles::YAOCHU_TYPES {
        if counts[t] > 0 {
            kinds += 1;
        }
        if counts[t] >= 2 {
            pair = 1;
        }
    }
    13 - kinds - pair
}

pub fn shanten(counts: &[u8; 34], melds: u8) -> i8 {
    let open = melds as i32;
    let mut best = standard(counts, open);
    if melds == 0 {
        best = best.min(chiitoi(counts)).min(kokushi(counts));
    }
    best as i8
}
